import hashlib, json, re
from html.parser import HTMLParser
from pathlib import Path
from urllib.parse import parse_qs, urlsplit

class Page(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.links = []
        self.text = []
        self.hidden = None

    def handle_starttag(self, tag, attrs):
        if tag in {'script', 'style'}:
            self.hidden = tag
        if tag == 'a':
            href = dict(attrs).get('href', '')
            if href.startswith('mailto:'):
                self.links.append(href)

    def handle_endtag(self, tag):
        if tag == self.hidden:
            self.hidden = None

    def handle_data(self, data):
        if self.hidden is None and data.strip():
            self.text.append(' '.join(data.split()))

folder = Path('products/distribution/catalogue-inquiry-usability')
raw = (folder / 'live-homepage.html').read_bytes()
prior = json.loads((folder / 'director-inquiry-template-check.json').read_text())
page = Page()
page.feed(raw.decode('utf-8'))
digest = hashlib.sha256(raw).hexdigest()
examples = {
    'en': 'We are preparing a catalogue migration. Could you scope a check for a repeated image reference within one style? These two fictional rows represent our source columns.',
    'fr': 'Nous préparons une migration de catalogue. Pourriez-vous préciser la portée d’une vérification des références d’image répétées pour un même modèle? Ces deux lignes fictives représentent nos colonnes source.'
}
rows = ['style,sku,image_reference', 'DEMO-1,DEMO-1-S,image-front.jpg', 'DEMO-1,DEMO-1-M,image-front.jpg']
inquiries = []
for link in page.links:
    query = parse_qs(urlsplit(link).query, keep_blank_values=True)
    subject = query.get('subject', [''])[0]
    template = query.get('body', [''])[0]
    for language, request in examples.items():
        body = '\n'.join((template.rstrip(), '', request, *rows)).strip()
        inquiries.append({'language': language, 'subject': subject, 'body': body, 'fictional_data_rows': len(rows) - 1, 'template_has_catalogue_marker': 'catalogue' in subject.casefold()})
terms = re.compile(r'20|anonym|synth|ficti|attachment|pièce jointe|plain text|texte brut|URL', re.I)
result = {'capture_sha256': digest, 'matches_prior_static_check': digest == prior.get('homepage_sha256'), 'scope': 'Fictional copy-and-paste rehearsal from a saved live capture. Requires review of the quoted wording before staging any site change.', 'visible_text_excerpts': [line for line in page.text if terms.search(line)][:30], 'example_inquiries': inquiries, 'out_of_scope_comparison': {'en': 'Please open the attached export or retrieve it from a link.', 'fr': 'Veuillez ouvrir le fichier joint ou récupérer le fichier à partir d’un lien.', 'operator_handling': 'Request a small fictional or anonymized excerpt pasted as plain text if consistent with the captured offer.'}, 'operator_scoping_questions': ['Does the source map style and image reference to these columns?', 'Is the requested check limited to source rows, or are before-and-after rows needed?'], 'mail_sent': False}
path = folder / 'director-bilingual-inquiry-rehearsal.json'
path.write_text(json.dumps(result, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
print(json.dumps({'path': str(path), 'matches_prior_static_check': result['matches_prior_static_check'], 'examples': len(inquiries), 'visible_excerpts': len(result['visible_text_excerpts'])}))
